export const COLLEGES = [
  { id: 'miet', short: 'MIET', name: 'Meerut Institute of Engineering & Technology', area: 'Baghpat Road Bypass', initials: 'MI', tone: 'violet', position: [28.9731, 77.6402], url: 'https://www.miet.ac.in/' },
  { id: 'ccs', short: 'CCS University', name: 'Chaudhary Charan Singh University', area: 'Ramgarhi, Meerut', initials: 'CC', tone: 'peach', position: [28.970, 77.741], url: 'https://www.ccsuniversity.ac.in/contact' },
  { id: 'iimt', short: 'IIMT University', name: 'IIMT University', area: 'Ganga Nagar · Mawana Road', initials: 'II', tone: 'mint', position: [29.031, 77.752], url: 'https://iimtu.edu.in/contact' },
  { id: 'subharti', short: 'Subharti University', name: 'Swami Vivekanand Subharti University', area: 'Subhartipuram · NH-58', initials: 'SU', tone: 'rose', position: [28.965, 77.646], url: 'https://subharti.org/' },
  { id: 'vidya', short: 'Vidya University', name: 'Vidya University · formerly Vidya Knowledge Park', area: 'Baghpat Bypass, Meerut', initials: 'VU', tone: 'blue', position: [28.959, 77.636], url: 'https://vidya.edu.in/admissions-contact-us' },
];

// Verified real room photos sourced from pgdekho.com (AWS S3 & platform media)
export const PGDEKHO_ROOM_PHOTOS = [
  'https://pgdekhoprod.s3.amazonaws.com/pgDekhoWeb/IMG-20250719-WA0144.jpg',
  'https://pgdekhoprod.s3.amazonaws.com/pgDekhoWeb/IMG_20250218_123829.jpg',
  'https://pgdekhoprod.s3.amazonaws.com/pgDekhoWeb/IMG-20250719-WA0143.jpg',
  'https://pgdekhoprod.s3.amazonaws.com/pgDekhoWeb/sura4.jpg',
  'https://pgdekhoprod.s3.ap-south-1.amazonaws.com/pgDekhoWeb/1768197790666-IMG_6303.jpeg',
  'https://pgdekhoprod.s3.ap-south-1.amazonaws.com/pgDekhoWeb/1785500816589-1785438746266-IMG_6632~2.jpeg',
  'https://pgdekho.com/static/media/guest-room-1.6971e2a84b9f89a87f1a.png',
  'https://pgdekhoprod.s3.ap-south-1.amazonaws.com/pgDekhoWeb/1787564596321-Screenshot%202026-08-24%20151133.png',
];

// Existing catalog records updated with PGdekho verified room photography
export const STAYS = [
  { id: 101, name: 'Sunrise Girls Hostel', rent: 8000, distance: 2, sharing: 2, ac: true, image: PGDEKHO_ROOM_PHOTOS[0], category: 'girls', tagline: 'A little room for your big plans.' },
  { id: 102, name: 'MIET Boys PG', rent: 6000, distance: 1, sharing: 3, ac: false, image: PGDEKHO_ROOM_PHOTOS[1], category: 'boys', tagline: 'More company. Less commute.' },
  { id: 103, name: 'Luxury Stay PG', rent: 12000, distance: 3, sharing: 1, ac: true, image: PGDEKHO_ROOM_PHOTOS[2], category: 'coed', tagline: 'Your own corner of the city.' },
  { id: 104, name: 'Budget Rooms', rent: 4000, distance: 5, sharing: 3, ac: false, image: PGDEKHO_ROOM_PHOTOS[3], category: 'boys', tagline: 'Keep a little more for the weekend.' },
  { id: 105, name: 'Elite Scholars Hostel', rent: 9000, distance: 2, sharing: 2, ac: true, image: PGDEKHO_ROOM_PHOTOS[4], category: 'boys', tagline: 'Settle in. Make it yours.' },
  { id: 106, name: 'Roorkee Road PG', rent: 5500, distance: 4, sharing: 2, ac: false, image: PGDEKHO_ROOM_PHOTOS[5], category: 'coed', tagline: 'A fresh start, within your budget.' },
  { id: 107, name: 'Campus View Hostel', rent: 7500, distance: 1, sharing: 2, ac: true, image: PGDEKHO_ROOM_PHOTOS[6], category: 'girls', tagline: 'A home base for campus life.' },
].map((stay) => ({ ...stay, college: 'miet' }));

export const getPropertyImage = (property) => {
  if (!property) return PGDEKHO_ROOM_PHOTOS[0];

  // 1. If property already has a custom/web photoUrl, use it
  if (property.photoUrl && typeof property.photoUrl === 'string') {
    const trimmed = property.photoUrl.trim();
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
      return trimmed;
    }
  }

  // 2. If it matches a named catalog stay
  const propertyName = property.pgName?.trim().toLocaleLowerCase();
  if (propertyName) {
    const catalogStay = STAYS.find((stay) => stay.name.toLocaleLowerCase() === propertyName);
    if (catalogStay && catalogStay.image) return catalogStay.image;
  }

  // 3. Deterministic hash to cycle through pgdekho verified photos
  const rawId = property.id ?? property.excelId ?? property.pgName ?? 0;
  const numId = typeof rawId === 'number' ? rawId : String(rawId).split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const photoIndex = Math.abs(numId) % PGDEKHO_ROOM_PHOTOS.length;

  return PGDEKHO_ROOM_PHOTOS[photoIndex];
};

export const money = (value) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);
